class Policy:
    # Track scores and use them to prioritize unsolved tasks, with round-robin fallback
    def __init__(self):
        self.scores = {}
        self.pick_count = 0

    def pick(self, keys, round_index):
        # Find unsolved tasks (score < 1.0) in current shard
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]

        if unsolved:
            # Among unsolved, prefer ones we haven't tried yet, then lowest score
            untried = [k for k in unsolved if k not in self.scores]
            if untried:
                # Round-robin among untried to explore broadly
                return untried[self.pick_count % len(untried)]
            else:
                # All tried but unsolved - pick the one with lowest score (most promising to improve)
                return min(unsolved, key=lambda k: self.scores[k])
        else:
            # All solved or unknown - fall back to round-robin
            return keys[round_index % len(keys)]

    def record(self, task_id, score):
        self.scores[task_id] = score
        self.pick_count += 1
