class Policy:
    # Changed: prioritize unsolved tasks, but when all are solved, pick the least-recently-attempted to maximize information gain
    def __init__(self):
        self.scores = {}  # task_id -> best score seen
        self.last_picked = {}  # task_id -> round_index when last picked

    def pick(self, keys, round_index):
        # Filter to tasks we haven't seen solved (score < 1.0)
        unsolved = [k for k in keys if self.scores.get(k, 0.0) < 1.0]
        if unsolved:
            # Among unsolved, prefer those we haven't tried recently (round-robin)
            # but also prefer ones we've never tried at all
            never_tried = [k for k in unsolved if k not in self.last_picked]
            if never_tried:
                return never_tried[0]
            # All unsolved have been tried; pick the one least recently picked
            return min(unsolved, key=lambda k: self.last_picked.get(k, -1))
        # All solved in shard — pick the least recently picked to avoid wasting on solved
        # but still make some progress (maybe scores are stale)
        return min(keys, key=lambda k: self.last_picked.get(k, -1))

    def record(self, task_id, score):
        # Keep the best score (solved status is what matters)
        if score > self.scores.get(task_id, 0.0):
            self.scores[task_id] = score
        # Update last picked time (we don't have round_index here, so just mark as picked)
        # We'll use a counter to track recency
        self.last_picked[task_id] = self.last_picked.get(task_id, 0) + 1
