class Policy:
    # Changed: use UCB1-style exploration to balance trying unsolved tasks vs. exploiting known-good ones
    def __init__(self):
        self.scores = {}  # task_id -> best score seen
        self.counts = {}  # task_id -> number of times picked

    def pick(self, keys, round_index):
        import math
        total_picks = sum(self.counts.get(k, 0) for k in keys)
        # UCB1: prefer tasks with high uncertainty (low count) and high score
        best_key = None
        best_ucb = -float('inf')
        for k in keys:
            score = self.scores.get(k, 0.0)
            count = self.counts.get(k, 0)
            if score >= 1.0:
                continue  # skip solved tasks
            if count == 0:
                # never tried — high priority
                ucb = float('inf')
            else:
                # exploitation + exploration bonus
                ucb = score + math.sqrt(2 * math.log(total_picks + 1) / count)
            if ucb > best_ucb:
                best_ucb = ucb
                best_key = k
        if best_key is None:
            # all solved — just pick first (won't happen often)
            return keys[0]
        return best_key

    def record(self, task_id, score):
        self.counts[task_id] = self.counts.get(task_id, 0) + 1
        if score > self.scores.get(task_id, 0.0):
            self.scores[task_id] = score
